import base64, concurrent.futures, hashlib, io, json, os, pathlib, shutil, subprocess, tempfile, urllib.error, urllib.parse, urllib.request

ROOT=pathlib.Path('/home/appontrack/public_html')
TARGET=ROOT/'ayo'
HOSTCFG=pathlib.Path('/home/appontrack/ontrack-voice-link/config.json')
REF='6b3a075ab031dcd3cb2686d6696cfec596a2e595'
REPO='OnTrack-Development/OnTrack-voice'
FILES=[
 'ayo/.htaccess','ayo/index.php','ayo/api.php','ayo/app.js',
 'ayo/style.css','ayo/audio-worklet.js','ayo/ontrack.json',
 'ayo/secure-vault.php','ayo/voice-expression.php',
 'ayo/ayo-avatar.js','ayo/ayo-mic-stt.js','ayo/assets/ayo-character.webp.b64'
]
class NoRedirect(urllib.request.HTTPRedirectHandler):
 def redirect_request(self,req,fp,code,msg,headers,url): return None

def fetch(arg):
 path,token=arg
 url='https://api.github.com/repos/'+REPO+'/contents/'+urllib.parse.quote(path,safe='/')+'?ref='+REF
 req=urllib.request.Request(url,headers={'Authorization':'Bearer '+token,'Accept':'application/vnd.github+json','User-Agent':'OnTrack-AYO-Direct-Release'})
 with urllib.request.urlopen(req,timeout=10) as r: data=json.loads(r.read(500000))
 if data.get('encoding')!='base64' or data.get('type')!='file': raise RuntimeError('Invalid GitHub source: '+path)
 raw=base64.b64decode(data['content'])
 blob=hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()
 if blob!=data.get('sha'): raise RuntimeError('Git blob mismatch: '+path)
 out='assets/ayo-character.webp' if path.endswith('.webp.b64') else path[4:]
 if path.endswith('.webp.b64'): raw=base64.b64decode(raw,validate=True)
 if len(raw)>400000: raise RuntimeError('Unexpected source size: '+path)
 return out,raw

def run():
 if os.getuid()!=2379 or not ROOT.is_dir() or ROOT.is_symlink() or TARGET.is_symlink(): raise RuntimeError('Wrong host account or path')
 if not HOSTCFG.is_file() or HOSTCFG.is_symlink() or HOSTCFG.stat().st_mode & 0o077: raise RuntimeError('Host GitHub credential store is not protected')
 token=json.loads(HOSTCFG.read_text())['token']
 if not isinstance(token,str) or len(token)<20: raise RuntimeError('Host GitHub credential unavailable')
 with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool:
  source=dict(pool.map(fetch,[(p,token) for p in FILES]))
 token=None
 if len(source)!=12: raise RuntimeError('Incomplete AYO sources')
 if not source['assets/ayo-character.webp'].startswith(b'RIFF') or source['assets/ayo-character.webp'][8:12]!=b'WEBP': raise RuntimeError('Invalid avatar')
 if b'DirectoryIndex index.php' not in source['.htaccess']: raise RuntimeError('AYO routing is not standalone')
 if not json.loads(source['ontrack.json']).get('plans'): raise RuntimeError('Invalid voice product data')
 php='/opt/cpanel/ea-php83/root/usr/bin/php'
 if not pathlib.Path(php).is_file(): php='/usr/bin/php'
 with tempfile.TemporaryDirectory(prefix='.ayo-release-',dir=str(ROOT)) as tmp:
  stage=pathlib.Path(tmp)/'ready'
  stage.mkdir(mode=0o755)
  for name,raw in source.items():
   f=stage/name
   f.parent.mkdir(parents=True,exist_ok=True)
   f.write_bytes(raw)
   f.chmod(0o644)
  for name in ['index.php','api.php','voice-expression.php','secure-vault.php']:
   c=subprocess.run([php,'-l',str(stage/name)],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=4)
   if c.returncode: raise RuntimeError('Host PHP lint error: '+name+': '+c.stderr.decode(errors='replace')[:180])
  node=shutil.which('node')
  if node:
   for name in ['app.js','ayo-avatar.js','ayo-mic-stt.js']:
    c=subprocess.run([node,'--input-type=module','--check'],input=source[name],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=4)
    if c.returncode: raise RuntimeError('JavaScript validation failed: '+name+': '+c.stderr.decode(errors='replace')[:180])
  (stage/'.ayo-release.json').write_text(json.dumps({'commit':REF,'files':len(source)}))
  (stage/'.ayo-release.json').chmod(0o644)
  (stage/'assets').chmod(0o755)
  stage.chmod(0o755)
  backup=None
  if TARGET.exists():
   if not TARGET.is_dir(): raise RuntimeError('Existing /ayo is not a directory')
   marker=TARGET/'.ayo-release.json'
   index=TARGET/'index.php'
   if not marker.is_file() and (not index.is_file() or 'AYO' not in index.read_text(encoding='utf8',errors='replace')[:10000]): raise RuntimeError('Unmanaged non-AYO /ayo: no overwrite')
   backups=pathlib.Path('/home/appontrack/.ayo-backups')
   backups.mkdir(mode=0o700,exist_ok=True)
   backups.chmod(0o700)
   backup=backups/('ayo-before-'+REF[:12]+'-'+str(os.getpid()))
   if backup.exists(): raise RuntimeError('AYO backup collision')
   os.replace(TARGET,backup)
  try: os.replace(stage,TARGET)
  except BaseException:
   if backup and backup.exists(): os.replace(backup,TARGET)
   raise
  req=urllib.request.Request('https://app.ontrackegy.com/ayo/',headers={'User-Agent':'OnTrack-AYO-Health/1','Cache-Control':'no-cache'})
  try:
   with urllib.request.build_opener(NoRedirect()).open(req,timeout=10) as r:
    page=r.read(250000).decode('utf8','replace')
    health={'http':r.status,'ayo_page':('AYO | OnTrack Voice Lab' in page)}
  except urllib.error.HTTPError as e: health={'http':e.code,'redirect':(e.headers.get('Location') or '')[:220]}
  except Exception as e: health={'error':type(e).__name__+': '+str(e)[:100]}
  result={'deployed':True,'commit':REF,'files':len(source),'path':'/ayo/','php_lint':'pass','js_checked':bool(node),'backup':bool(backup),'live_http':health}
  print(json.dumps(result),flush=True)
  if health.get('http')!=200 or not health.get('ayo_page'): raise RuntimeError('AYO public URL is not yet reachable')

run()
